 private static NativeScreenEntity create(Minecraft mc,ScreenFamily family,ScreenFamily.State state,BlockPos pos,CompoundTag saved){var level=mc.level;need(level.getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4)!=null,"fixture never stages in cold chunk "+pos);level.setBlock(pos,ScreenBlockChecks.block(family).state(state),18);var tile=(NativeScreenEntity)level.getBlockEntity(pos);tile.loadWithComponents(saved.copy(),level.registryAccess());need(!tile.inert(),"source snapshot installs "+family+" pos="+pos);return tile;}
